// Verbatim sections: copied byte-for-byte from source, never paraphrased or restyled (content rule 7).
// These come from the fixed report template + parsed kick-off deck fields.
// FIX: engagement fields (title/quarter/year/entity) come from a real Get Engagement read now —
// the trigger's passthrough data only ever carries whatever Intake & Parse forwarded (per-file
// classification items), never the engagement row itself, so reading them off the trigger silently
// produced 'undefined' for every field (found via test execution).
const e = $('Get Engagement').first().json;
const k = $('When Executed by Orchestrator').first().json; // kick-off fields: still pending the kickoff-deck parser (Increment 2)
return [{ json: {
  cover_page: { title: e.title, quarter: e.quarter, year: e.year, entity: e.entity, status: 'Draft Report' },
  objectives: k.kickoff_objectives,
  scope: { review_period: k.kickoff_review_period, items: k.kickoff_scope_items, limitations: k.kickoff_scope_limitations || null },
  limitations_of_internal_audit: 'STANDARD_TEMPLATE_TEXT',
  risk_classification: 'STANDARD_TEMPLATE_TEXT'
}}];

// Fill sections: fixed sentence structure, names/areas substituted from kickoff deck (content rule per FR-09/FR-10).
// FIX: acknowledged_department and audit_team live on the engagement row (set at intake / pre-filled
// from kickoff deck), not on the trigger passthrough — same class of bug as Assemble Verbatim Sections.
const e = $('Get Engagement').first().json;
return [{ json: {
  acknowledgment: `We wish to place on record our appreciation for the co-operation and assistance rendered to us by ${e.acknowledged_department} teams.`,
  audit_team: e.audit_team
}}];

// v0.2: opinion library moved from an embedded/provisional list to held configuration (D-2 resolved) —
// read the latest version of the configuration row instead of hardcoding the library in this workflow.
// FIX: overall_opinion_label comes from the real engagement row, not the trigger passthrough.
const rows = $input.all().map(i => i.json);
const latest = rows.reduce((a, b) => (!a || b.version > a.version) ? b : a, null);
const library = latest?.content || {};
const label = $('Get Engagement').first().json.overall_opinion_label;
return [{ json: { overall_opinion_paragraph: library[label] ?? null } }];

// v0.2: entity logo moved to held configuration, selected by entity rather than uploaded per engagement.
// Not yet consumed by the render service (pre-existing known gap — the render service doesn't place
// logos at all yet), but the lookup itself is wired now so it's ready when that's built.
const rows = $input.all().map(i => i.json);
const latest = rows.reduce((a, b) => (!a || b.version > a.version) ? b : a, null);
return [{ json: { entity_logo_ref: latest?.file_ref ?? null } }];

// Background is GENERATED, not verbatim (content rule + FR-05) — the one section here that involves
// LLM judgement, constrained to the notification, process understanding and working-file context,
// plus the analysis sheet if supplied (min. one introductory paragraph if not).
const hasAnalysisSheet = $('When Executed by Orchestrator').first().json.input_gaps?.includes('analysis_sheet') === false;
return [{ json: { background_llm_prompt_ready: true, include_analysis_placement: hasAnalysisSheet } }];
